import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { bookingAPI, reviewAPI } from '../services/api';
import { useAuth } from '../context/AuthContext';

const CreateReview = () => {
  const { id } = useParams(); // id de la salle
  const navigate = useNavigate();
  const { user } = useAuth();
  
  const [completedBookings, setCompletedBookings] = useState([]);
  const [selectedBooking, setSelectedBooking] = useState('');
  const [reviewData, setReviewData] = useState({
    rating: 5,
    comment: ''
  });
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!user) {
      navigate('/login');
      return;
    }
    
    fetchCompletedBookings();
  }, [id, user, navigate]);

  // Fonction pour récupérer uniquement les réservations TERMINÉES
  const fetchCompletedBookings = async () => {
    setLoading(true);
    try {
      const response = await bookingAPI.getMyBookings();
      
      // Filtrer pour ne garder que les réservations TERMINÉES pour cette salle
      const completed = (response.data.bookings || []).filter(booking => 
        booking.room_id === parseInt(id) && 
        booking.status === 'completed' // SEULEMENT LES TERMINÉES
      );
      
      setCompletedBookings(completed);
      
      if (completed.length === 1) {
        setSelectedBooking(completed[0].id.toString());
      }
    } catch (error) {
      console.error('Erreur:', error);
      setError('Impossible de charger vos réservations');
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (e) => {
    setReviewData({
      ...reviewData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    if (!selectedBooking) {
      setError('Veuillez sélectionner une réservation terminée');
      return;
    }

    try {
      const payload = {
        booking_id: parseInt(selectedBooking),
        rating: parseInt(reviewData.rating),
        comment: reviewData.comment
      };

      const response = await reviewAPI.create(payload);
      
      if (response.success) {
        setSuccess('✅ Avis publié avec succès !');
        setTimeout(() => {
          navigate(`/rooms/${id}`);
        }, 2000);
      }
    } catch (error) {
      setError(error.message || 'Erreur lors de la publication');
    }
  };

  return (
    <div className="main-content">
      <div className="card">
        <h1>📝 Laisser un avis</h1>
        <p>Partagez votre expérience après votre réservation</p>
      </div>

      <div className="card">
        {error && <div className="alert alert-error">{error}</div>}
        {success && <div className="alert alert-success">{success}</div>}

        {loading ? (
          <p>Chargement...</p>
        ) : completedBookings.length === 0 ? (
          <div className="no-bookings">
            <h3>⚠️ Impossible de laisser un avis</h3>
            <p>Vous ne pouvez laisser un avis que si :</p>
            <ul>
              <li>✅ Vous avez réservé cette salle</li>
              <li>✅ Votre réservation est <strong>terminée</strong> (statut: "completed")</li>
              <li>✅ Vous n'avez pas déjà laissé d'avis pour cette réservation</li>
            </ul>
            <p><strong>Note :</strong> Une réservation devient "terminée" automatiquement après la date de fin.</p>
            <Link to={`/rooms/${id}`} className="btn btn-primary">
              ← Retour à la salle
            </Link>
            <Link to="/dashboard" className="btn btn-secondary" style={{ marginLeft: '10px' }}>
              Voir mes réservations
            </Link>
          </div>
        ) : (
          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label className="form-label">Sélectionner une réservation terminée</label>
              <select
                className="form-input"
                value={selectedBooking}
                onChange={(e) => setSelectedBooking(e.target.value)}
                required
              >
                <option value="">-- Choisir une réservation --</option>
                {completedBookings.map(booking => (
                  <option key={booking.id} value={booking.id}>
                    Réservation #{booking.id} - {new Date(booking.start_datetime).toLocaleDateString('fr-FR')}
                  </option>
                ))}
              </select>
              <small>Seules les réservations <strong>terminées</strong> sont affichées</small>
            </div>

            <div className="form-group">
              <label className="form-label">Note</label>
              <div className="rating">
                {[1, 2, 3, 4, 5].map(star => (
                  <button
                    key={star}
                    type="button"
                    onClick={() => setReviewData({...reviewData, rating: star})}
                    className={`star ${reviewData.rating >= star ? 'active' : ''}`}
                  >
                    ⭐
                  </button>
                ))}
              </div>
              <p>Note sélectionnée : <strong>{reviewData.rating}/5</strong></p>
            </div>

            <div className="form-group">
              <label className="form-label">Commentaire (optionnel)</label>
              <textarea
                name="comment"
                className="form-input"
                value={reviewData.comment}
                onChange={handleChange}
                rows="4"
                placeholder="Partagez votre expérience..."
              />
            </div>

            <div className="form-buttons">
              <button type="submit" className="btn btn-primary">
                Publier l'avis
              </button>
              <Link to={`/rooms/${id}`} className="btn btn-secondary">
                Annuler
              </Link>
            </div>
          </form>
        )}
      </div>
    </div>
  );
};

export default CreateReview;
